func (f DecompressStreamFlatFuture) Wait() (uint64, []byte, uint64, error) {
	if f.c == nil {
		return 0, nil, 0, rt.ErrFutureUsed
	}
	d, err := f.c.c.Wait(f.call, f.id)
	if err != nil {
		return 0, nil, 0, err
	}
	defer d.Release()
	b := d.Body
	// G2: ret size @0, srcPos size @8 (size 16); V2: dst from 16; a failure carries a detail string at 16.
	if len(b) < 16 {
		return 0, nil, 0, d.Malformed()
	}
	ret := hqqLE.Uint64(b[0:])
	if d.Fail {
		return 0, nil, 0, d.LibError("ZSTD_decompressStream_flat", int64(ret), 16)
	}
	if d.Detail {
		return 0, nil, 0, d.Malformed()
	}
	n, end, err := rt.GetBytesInto(f.dst, b, 16)
	if err != nil || end != len(b) {
		return 0, nil, 0, d.Malformed()
	}
	return ret, f.dst[:n], hqqLE.Uint64(b[8:]), nil
}
